    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/`([^`]+)`/g, '<code>$1</code>');
  const paragraphs = html.split('\n\n');
  return paragraphs
    .map(p => p.trim()
      ? p.startsWith('<h') ? p : `<p>${p}</p>`
